            local next_ = pickNextEnabled()
            if next_ ~= currentTask then
                currentTask = next_
                log(S(285) .. (currentTask and currentTask.name or S(15)))
            end
            sliceEnd = now + SLICE_SECONDS
        end
        if currentTask then
            local ok, err = pcall(currentTask.step)
            if not ok then
                log(S(247) .. currentTask.name .. S(56) .. tostring(err))
            end
        end
    end)
end
